import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DcNbVdPy.js";var i=JSON.parse(`{"title":"Versioning","description":"How to choose a Changeset level for a package change.","frontmatter":{"title":"Versioning","description":"How to choose a Changeset level for a package change.","group":"Documents","category":"Guides","head":[["meta",{"property":"og:title","content":"Versioning"}],["meta",{"property":"og:description","content":"How to choose a Changeset level for a package change."}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/guide/versioning"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/guide/versioning"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/guide/versioning.md"}},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md","lastUpdated":1794201618000}`),a={name:`guide/versioning.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="package-versioning" tabindex="-1">Package versioning <a class="header-anchor" href="#package-versioning" aria-label="Permalink to “Package versioning”">​</a></h1><p>Choose a Changeset level for each affected package based on its current version in <code>package.json</code>.</p><table tabindex="0"><thead><tr><th>Current package version</th><th>Breaking change</th><th>Feature</th><th>Fix or performance improvement</th></tr></thead><tbody><tr><td>Below <code>1.0.0</code></td><td><code>minor</code></td><td><code>patch</code></td><td><code>patch</code></td></tr><tr><td><code>1.0.0</code> or later</td><td><code>major</code></td><td><code>minor</code></td><td><code>patch</code></td></tr></tbody></table><p>Treat a change as breaking when existing users must change code or configuration to keep working. Removing or renaming a public API and changing a supported format incompatibly are breaking changes. Changes to public types or signatures are breaking when existing calls no longer type-check. Additive capabilities are features. Fixes and performance improvements use <code>patch</code>.</p><p>When one change affects multiple packages, classify each package separately. The fixed group in <code>.changeset/config.json</code> may propagate the highest required bump to its other members, but it does not change how you classify the packages directly affected by the change.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};